<script setup lang="ts">
import { api, friendlyError } from '@lostsky/api/client'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import LsButton from '@lostsky/ui/components/LsButton.vue'
import { File, Search, Trash2, Upload } from '@lucide/vue'
import { computed, ref } from 'vue'
const client=useQueryClient();const page=ref(1);const keyword=ref('');const input=ref<HTMLInputElement|null>(null);const uploading=ref(false)
const usage=useQuery({queryKey:['file-usage'],queryFn:()=>api.get<Record<string,unknown>>('/file/usage')})
const query=useQuery({queryKey:computed(()=>['files',page.value,keyword.value]),queryFn:()=>api.get<Record<string,unknown>>('/file/index',{page:page.value,limit:18,keyword:keyword.value})})
const files=computed<Record<string,unknown>[]>(()=>Array.isArray(query.data.value?.list)?query.data.value!.list as Record<string,unknown>[]:[]);const total=computed(()=>Number(query.data.value?.total??files.value.length));const pages=computed(()=>Math.max(1,Math.ceil(total.value/18)))
const remove=useMutation({mutationFn:(id:number)=>api.post('/file/delete',{id}),onSuccess:async()=>{await Promise.all([client.invalidateQueries({queryKey:['files']}),client.invalidateQueries({queryKey:['file-usage']})])}})
async function upload(event:Event){const list=Array.from((event.target as HTMLInputElement).files??[]);if(!list.length)return;uploading.value=true;try{for(const file of list)await api.upload(file);await Promise.all([client.invalidateQueries({queryKey:['files']}),client.invalidateQueries({queryKey:['file-usage']})])}finally{uploading.value=false;if(input.value)input.value.value=''}}
function size(value:unknown){const bytes=Number(value)||0;if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
function removeFile(id:number){if(window.confirm('确认删除此文件？'))remove.mutate(id)}
</script>
<template><div class="files"><header><div><p>已使用 {{size(usage.data.value?.total_size??usage.data.value?.totalSize)}} · {{usage.data.value?.count??total}} 个文件</p><h2>团队文件</h2></div><LsButton :loading="uploading" @click="input?.click()"><Upload :size="17"/>上传文件</LsButton><input ref="input" class="hidden" type="file" multiple @change="upload"></header><label class="search"><Search :size="18"/><span class="ls-sr-only">搜索文件</span><input v-model="keyword" type="search" placeholder="按名称搜索" @input="page=1"></label><p v-if="query.isError.value" class="error" role="alert">{{friendlyError(query.error.value)}}</p><div v-else-if="query.isPending.value" class="loading"><span v-for="i in 6" :key="i"/></div><div v-else-if="!files.length" class="empty"><File :size="32"/><h3>还没有文件</h3><p>上传团队需要共享的第一份资料。</p></div><div v-else class="file-grid"><article v-for="item in files" :key="String(item.id)"><div class="file-icon"><File/></div><div><strong>{{item.name||item.original_name||'未命名文件'}}</strong><small>{{item.mime_type||item.ext||'未知格式'}} · {{size(item.size)}}</small></div><a v-if="item.url" :href="String(item.url)" target="_blank" rel="noopener noreferrer">打开</a><button type="button" aria-label="删除文件" @click="removeFile(Number(item.id))"><Trash2 :size="17"/></button></article></div><footer v-if="pages>1"><LsButton variant="secondary" size="sm" :disabled="page<=1" @click="page--">上一页</LsButton><span>第 {{page}} / {{pages}} 页</span><LsButton variant="secondary" size="sm" :disabled="page>=pages" @click="page++">下一页</LsButton></footer></div></template>
<style scoped>.files{display:grid;gap:1rem}header{display:flex;align-items:end;justify-content:space-between;gap:1rem;flex-wrap:wrap}header p,header h2{margin:0}header p{color:var(--muted-ink);font-size:.82rem}header h2{margin-top:.2rem}.hidden{display:none}.search{height:44px;display:flex;align-items:center;gap:.5rem;padding:0 .75rem;background:white;border:1px solid var(--line);border-radius:8px}.search input{width:100%;border:0;outline:0}.file-grid{display:grid;gap:.65rem}.file-grid article{display:grid;grid-template-columns:44px minmax(0,1fr) auto auto;align-items:center;gap:.75rem;padding:.85rem;background:white;border:1px solid var(--line);border-radius:10px}.file-icon{width:44px;height:44px;display:grid;place-items:center;color:var(--sky-lost-strong);background:var(--cloud);border-radius:8px}.file-grid strong,.file-grid small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-grid small{margin-top:.2rem;color:var(--muted-ink);font-size:.75rem}.file-grid a,.file-grid button{min-width:44px;min-height:44px;display:grid;place-items:center;color:var(--sky-lost-strong);background:transparent;border:0}.file-grid button{color:var(--danger)}footer{display:flex;align-items:center;justify-content:center;gap:1rem;color:var(--muted-ink);font-size:.8rem}.empty,.error{padding:3rem 1rem;text-align:center;background:white;border:1px solid var(--line);border-radius:10px}.empty svg{color:var(--sky-lost-strong)}.error{padding:1rem;color:var(--danger);text-align:left}.loading{display:grid;gap:.6rem}.loading span{height:72px;background:var(--line);border-radius:10px}@media(min-width:760px){.file-grid{grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}}</style>
